    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Check for whisker blind zone
    if front == 3.0:
        # In blind zone: apply forward force to escape
        fx = 30.0
        fy = 0.0
    else:
        # Not in blind zone: proceed with navigation
        if y > 0.5:
            # Move down to floor
            fx = 0.0
            fy = -100.0
        else:
            # Move forward
            if x < 5.0:
                fx = 30.0
            else:
                fx = 10.0 * (7.0 - x) - 5.0 * vxd

