                fy = 10.0
            elif front > 3.0:
                # Move forward
                fx = 30.0
            else:
                # Moderate distance, move forward
                fx = 30.0

            # Maintain center height based on whiskers
            if up < 0.5:
                # Close to ceiling, move down
                fy = -100.0
            elif down < 0.5:
                # Close to floor, move up
                fy = 100.0
            else:
                # Maintain center height
                fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if in activation zone
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0

    if state["phase"] == "APPROACH":
        # Apply calculated force
        fx, fy = fx, fy
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)

        # Apply backward force to unlock
        fx_cmd = cfg["bfx"] - 1.0  # -35.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp

