            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p

        # Check for one-way assist
        if cfg["act_lo"] <= x <= cfg["act_hi"]:
            if vx_p > 0.0:
                # Apply leftward force to counteract assist
                fx_cmd -= 10.0

        # Check structural impulse limit
        impulse = math.hypot(agent_body.linearImpulse.x, agent_body.linearImpulse.y)
        if impulse > 250.0:
            scale = 250.0 / impulse
            fx_cmd *= scale
            fy_cmd *= scale

        # Ensure speed is below threshold
        if spd > 95.0:
            # Decelerate
            fx_cmd = max(fx_cmd, -50.0)
            fy_cmd = max(fy_cmd, -50.0)

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1

        # Check unlock conditions
        if cfg["act_lo"] <= x <= cfg["act_hi"]:
            if fx_cmd < cfg["bfx"] and spd < cfg["bspd"]:
                state["unlock_count"] += 1
                if state["unlock_count"] >= 5:
                    state["phase"] = "ESCAPE"
                    state["unlock_count"] = 0
            else:
                state["unlock_count"] = 0
        else:
            state["unlock_count"] = 0

    elif state["phase"] == "ESCAPE":
        x, y = pd[0], pd[1]
        if x >= 15.0 and 0.5 <= y <= 2.5:
            state["phase"] = "HOLD"
        else:
            # Apply force towards exit
            if x < 15.0:
                fx = 15.0
            else:
                fx = 0.0
            fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
            fx, fy = fx, fy

    elif state["phase"] == "HOLD":
        x, y = pd[0], pd[1]
        # Apply force to maintain position in exit zone
        if x < 15.0:
            fx = 15.0
        else:
            fx = 0.0
        if y < 0.5:
            fy = 100.0
        elif y > 2.5:
            fy = -100.0
        else:
            fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        fx, fy = fx, fy

    sandbox.apply_agent_force(fx, fy)

