import math

ACTIVATION_X_MIN = 5.0
ACTIVATION_X_MAX = 10.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0

class Memory:
    def __init__(self):
        self.data = {
            "phase": "APPROACH",
            "t": 0,
            "unlock_count": 0,
            "last_commanded_fx": 0.0,
            "last_commanded_fy": 0.0,
            "total_impulse": 0.0,
        }

    def clear(self):
        self.data = {
            "phase": "APPROACH",
            "t": 0,
            "unlock_count": 0,
            "last_commanded_fx": 0.0,
            "last_commanded_fy": 0.0,
            "total_impulse": 0.0,
        }

MEM = Memory()

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    state = MEM.data
    pd = sandbox.get_agent_position()
    front, up, down = sandbox.get_whisker_readings()
    x, y = pd
    vxd, vyd = sandbox.get_agent_velocity()
    impulse_limit = 250.0
    time_step = TIME_STEP

    fx = 0.0
    fy = 0.0

    if state["phase"] == "APPROACH":
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX:
            state["phase"] = "UNLOCK"
            state["t"] = 0
            state["unlock_count"] = 0
        else:
            if front < 2.0:
                fx = -20.0
            elif up < 1.0:
                fy = -20.0
            elif down < 1.5:
                fy = 20.0
            else:
                fx = 20.0
    elif state["phase"] == "UNLOCK":
        if not (ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX):
            state["phase"] = "APPROACH"
            state["t"] = 0
            state["unlock_count"] = 0
        else:
            fx_cmd = -50.0
            fy_cmd = 0.0
            spd = math.hypot(vxd, vyd)
            if spd >= BACKWARD_SPEED_MAX:
                fx_cmd = -10.0
            impulse = math.hypot(fx_cmd, fy_cmd) * time_step
            state["total_impulse"] += impulse
            if state["total_impulse"] > impulse_limit:
                scale = impulse_limit / state["total_impulse"]
                fx_cmd *= scale
                fy_cmd *= scale
                state["total_impulse"] = impulse_limit
            state["last_commanded_fx"] = fx_cmd
            state["last_commanded_fy"] = fy_cmd
            if fx_cmd < BACKWARD_FX_THRESHOLD and spd < BACKWARD_SPEED_MAX:
                state["unlock_count"] += 1
                if state["unlock_count"] >= 5:
                    state["phase"] = "ESCAPE"
                    state["unlock_count"] = 0
            else:
                state["unlock_count"] = 0
            state["t"] += 1
    elif state["phase"] == "ESCAPE":
        fx = 20.0
        if x >= EXIT_X_MIN and 0.5 <= y <= 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx = 0.0

    sandbox.apply_agent_force(fx, fy)
    MEM.data = state
